import cli from 'cli-forge';

const app = cli('argument-types').command('deploy', {
  builder: (args) =>
    args
      .positional('target', {
        type: 'string',
        required: true,
        description: 'Where to deploy (e.g. production, staging)',
      })
      .option('name', {
        type: 'string',
        description: 'Release name',
        default: 'latest',
      })
      .option('port', {
        type: 'number',
        description: 'Port to listen on',
        default: 3000,
      })
      .option('tags', {
        type: 'array',
        items: 'string',
        description: 'Tags to apply (space, comma, or repeated flag)',
        default: [],
      })
      .option('verbose', {
        type: 'boolean',
        description: 'Enable verbose logging',
        default: false,
      })
      ,
  handler: (args) => {
    console.log(
      `name=${args.name} port=${args.port} verbose=${args.verbose} tags=${args.tags.join(',')} target=${args.target}`
    );
  },
});

export default app;

if (require.main === module) {
  (async () => {
    await app.forge();
  })();
}

import cliForge from 'cli-forge';

const cli = cliForge('basic-cli')
  // Requires a command to be provided
  .demandCommand()

  // Registers "hello" command
  .command('hello', {
    // Builder is used to define the command's options
    builder: (args) =>
      args.option('name', {
        type: 'string',
        description: 'The name to say hello to',
        default: 'World',
      }),
    // Handler is used to define the command's behavior
    handler: (args) => {
      // Note: name is always defined because it has a default value.
      console.log(`Hello, ${args.name}!`);
    },
  })
  .command('goodbye', {
    builder: (args) =>
      args
        .option('name', {
          type: 'string',
          description: 'The name to say goodbye to',
          default: 'World',
        })
        .option('excited', {
          type: 'boolean',
          description: 'Whether to say goodbye excitedly',
        }),
    handler: (args) => {
      // Note the typing of `args` here. It's inferred from the builder.
      // The `name` option is always defined because it has a default value.
      // The `excited` option is optional because it doesn't have a default value.
      console.log(`Goodbye, ${args.name}${args.excited ? '!' : '.'}`);
    },
  });

// We export the CLI for a few reasons:
// - Testing
// - Composition (a CLI can be a subcommand of another CLI)
// - Docs generation
export default cli;

// Calling `.forge()` executes the CLI. It's single parameter is the CLI args
// and they default to `process.argv.slice(2)`.
if (require.main === module) {
  (async () => {
    await cli.forge();
  })();
}

import { ArgumentsOf, chain, cli, CLI, makeComposableBuilder } from 'cli-forge';

const withName = makeComposableBuilder((args) =>
  args.option('name', {
    type: 'string',
    description: 'Your name',
    required: true,
  })
);

const withAge = makeComposableBuilder((args) =>
  args.option('age', {
    type: 'number',
    description: 'Your age',
    required: true,
  })
);

const builder = <T extends CLI>(args: T) => chain(args, withName, withAge);

const myCLI = cli('arguments-of', {
  builder: (args) => builder(args),
  handler: (args) => CLIHandler(args),
});

type Arguments = ArgumentsOf<typeof builder>;

function CLIHandler(args: Arguments) {
  console.log(`Hello, ${args.name}!`);
  console.log(`You are ${args.age.toFixed(0)} years old.`);
}

if (require.main === module) {
  (async () => {
    await myCLI.forge();
  })();
}

import cliForge from 'cli-forge';

const cli = cliForge('basic-cli')
  .demandCommand()
  .command('hello', {
    builder: (args) =>
      args
        .option('name', {
          type: 'string',
          description: 'The name to say hello to',
          required: true,

          // Choices limits valid values for the option.
          // If the provided value is not in the choices array, an error will be thrown.
          choices: ['sir', 'madame'],
        })
        .option('phrase', {
          type: 'string',
          default: 'hello',

          // Choices can also be provided as a function that returns an array of valid values.
          // This can be useful if the choices are dynamic or need to be calculated at runtime.
          choices: () => ['hello', 'hi', 'hey'],
        }),
    // Handler is used to define the command's behavior
    handler: (args) => {
      // Note: args.name is typed as 'sir' | 'madame' due to the choices array
      console.log(`${args.phrase}, ${args.name}!`);
    },
  });

export default cli;

if (require.main === module) {
  (async () => {
    await cli.forge();
  })();
}

import { UnknownCLI, chain, cli, makeComposableBuilder } from 'cli-forge';

// -- Reusable option definitions --

// Manual generic approach (uses UnknownCLI as the constraint)
function withName<T extends UnknownCLI>(argv: T) {
  return argv.option('name', {
    type: 'string',
    description: 'Your name',
    required: true,
  });
}

const withGreeting = makeComposableBuilder((args) =>
  args.option('greeting', {
    type: 'string',
    description: 'The greeting to use',
    default: 'Hello',
  })
);

const withFarewell = makeComposableBuilder((args) =>
  args.option('farewell', {
    type: 'string',
    description: 'The farewell to use',
    default: 'Goodbye',
  })
);

// -- Commands with return values --

const withGreetCommand = makeComposableBuilder((args) =>
  args.command('greet', {
    builder: (args) => chain(args, withName, withGreeting),
    handler: (args): string => {
      const message = `${args.greeting}, ${args.name}!`;
      console.log(message);
      return message;
    },
  })
);

const withFarewellCommand = makeComposableBuilder((args) =>
  args.command('farewell', {
    builder: (args) => chain(args, withName, withFarewell),
    handler: (args): string => {
      const message = `${args.farewell}, ${args.name}!`;
      console.log(message);
      return message;
    },
  })
);

const withConverseCommand = makeComposableBuilder((args) =>
  args.command('converse', {
    description: 'A quick chat',
    builder: (args) => chain(args, withName),
    handler: (args) => {
      console.log(`[${args.name}]: hello!`);
    },
  })
);

// -- Parent command accessing children --

cli('composable-options', {
  builder: (args) =>
    chain(args, withGreetCommand, withFarewellCommand, withConverseCommand),

  handler: async (_args, ctx) => {
    const children = ctx.command.getChildren();

    // Handlers are typed - greetHandler returns string
    const greetHandler = children.greet.getHandler();
    if (greetHandler) {
      const result = greetHandler({ name: 'Alice', greeting: 'Hi' });
      console.log('Greeting ends with !:', result.endsWith('!'));
    }

    console.log('Available commands:', Object.keys(children).join(', '));
  },
}).forge();

import cli from 'cli-forge';

cli('conflicts-and-implications', {
  builder: (args) =>
    args
      .option('source', {
        describe: 'Source database',
        type: 'string',
      })
      .option('target', {
        describe: 'Target database',
        type: 'string',
      })
      .option('dry-run', {
        describe: 'Simulate the migration without making changes',
        type: 'boolean',
      })
      .option('force', {
        describe: 'Force the migration even if there are warnings',
        type: 'boolean',
      })
      .option('backup', {
        describe: 'Where should the backup be stored',
        type: 'string',
      })
      // Conflicts creates mutually exclusive arguments. Validation will throw an error if both options are provided.
      // In this case, it makes sense that the user wouldn't want to both simulate and force a migration.
      .conflicts('dry-run', 'force')

      // Implies creates mutually required arguments. Validation will throw an error if the first argument is provided without the second.
      // Practically in this case, this means that if the user provides the --force option, they must also provide the --backup option.
      .implies('force', 'backup'),
  handler: (_args) => {
    // ...
  },
}).forge();

import cliForge from 'cli-forge';

const cli = cliForge('default-values').command('$0', {
  builder: (args) =>
    args
      .option('name', {
        type: 'string',
        description: 'The name to say hello to',
        // Setting the default value directly
        default: 'World',
      })
      .option('greeting', {
        type: 'string',
        description: 'The greeting to use',
        // Setting the default value to an object containing a value and a description
        default: {
          // The value here may be different across command runs. In docs,
          // we want a consistent description of the default value.
          value: process.env['DEFAULT_VALUES_HELLO'] ?? 'Hello',
          description: 'The default greeting',
        },
      })
      .option('farewell', {
        type: 'string',
        description: 'The farewell to use',
        // Setting the default value to an object containing a function that returns a value and a description
        default: {
          // The value here may be different across command runs. In docs,
          // we want a consistent description of the default. Using a factory function
          // gives more flexibility compared to the value + description method above.
          factory: () => {
            if (process.arch === 'x64') {
              return 'Goodbye';
            } else {
              return 'Goodnight';
            }
          },
          description: 'The default farewell',
        },
      }),
  handler: (args) => {
    console.log(`${args.greeting}, ${args.name}!`);
    console.log(`${args.farewell}, ${args.name}!`);
  },
});

export default cli;

if (require.main === module) {
  (async () => {
    await cli.forge();
  })();
}

import cli from 'cli-forge';

const app = cli('lifecycle', {
  builder: (argv) => {
    // Phase 1, step 1 — The root builder runs first. In this example,
    // the root options are registered inline (above) rather than in a
    // builder callback, but the effect is the same. The builder is where
    // options, middleware, init hooks, and subcommands are registered.
    console.log('[1. root builder]');

    // ──────────────────────────────────────────────────────────
    // ROOT LEVEL — options, middleware, init hook
    // ──────────────────────────────────────────────────────────

    return (
      argv
        .option('format', {
          type: 'string',
          description: 'Output format',
          // Default: applied during normalization (before validation)
          default: 'text',
          // Coerce: runs after the value is parsed, transforms the raw value
          coerce: (v: string) => v.toLowerCase(),
        })

        .option('verbose', {
          type: 'boolean',
          description: 'Enable verbose output',
          default: false,
        })

        // Phase 1, step 3 — Middleware runs BEFORE init hooks at each command
        // level. This lets init hooks depend on middleware-computed values.
        .middleware((args) => {
          console.log('[2. root middleware] format =', args.format);
          return {
            ...args,
            // Middleware can add derived values that later stages can use
            isJson: args.format === 'json',
          };
        })

        // Phase 1, step 4 — Init hooks run after middleware, with access to
        // middleware-transformed args. They can dynamically register commands.
        .init((app, args) => {
          console.log(
            '[3. root init hook] isJson =',
            args.isJson,
            '(set by middleware)'
          );

          // Dynamically register the "deploy" command based on parsed args.
          // In real CLIs this is useful for plugin loading: read a config,
          // then register commands based on what plugins are configured.
          app.command('deploy', {
            // Phase 1 (next iteration) step 1 — Subcommand builder runs
            // lazily when "deploy" is discovered in unmatched tokens.
            builder: (cmd) => {
              console.log('[4. deploy builder]');
              return (
                cmd
                  .option('target', {
                    type: 'string',
                    description: 'Deployment target',
                    required: true,
                  })
                  .option('dry-run', {
                    type: 'boolean',
                    description: 'Simulate without making changes',
                  })
                  .option('force', {
                    type: 'boolean',
                    description: 'Skip safety checks',
                  })
                  .option('backup-path', {
                    type: 'string',
                    description:
                      'Backup location (required when --force is used)',
                  })
                  // Conflicts: --dry-run and --force are mutually exclusive
                  // (validated during Phase 2 final parse)
                  .conflicts('dry-run', 'force')
                  // Implies: --force requires --backup-path
                  // (validated during Phase 2 final parse)
                  .implies('force', 'backup-path')
                  // Subcommand-level middleware runs in Phase 1 for this level,
                  // before the subcommand's init hooks.
                  .middleware((a) => {
                    console.log('[5. deploy middleware] target =', a.target);
                    return a;
                  })
                  // Subcommand-level init hook
                  .init((subcli, a) => {
                    console.log('[6. deploy init hook] verbose =', a.verbose);
                    // Could register nested subcommands here, modify options, or other stuff.
                    // Most typically not needed for registering commands or options, but could
                    // make sense in some cases (e.g. options that's registration depends on another
                    // option flag. Things like a --config path that includes plugins which register
                    // commands are one of the very few cases that it would make sense.)
                  })
              );
            },

            // Phase 2 step 3 — Handler runs after final validation passes.
            // At this point all options have been through:
            // defaults → env → config → coerce → required → choices →
            // conflicts → implies → custom validate
            handler: (args) => {
              console.log('[7. handler] deploying to', args.target);
              if (args.verbose) {
                console.log('  format:', args.format);
                console.log('  dry-run:', args['dry-run']);
              }
            },
          });
        })
    );
  },
});

export default cli;

if (require.main === module) {
  (async () => {
    await app.forge();
  })();
}

import { cli } from 'cli-forge';
import i18next from 'i18next';

async function main() {
  // Initialize i18next with translations for multiple locales
  await i18next.init({
    lng: 'en-US', // Set default language
    fallbackLng: 'en-US',
    resources: {
      'en-US': {
        translation: {
          name: 'name',
          port: 'port',
          verbose: 'verbose',
          serve: 'serve',
          build: 'build',
        },
      },
      'es-ES': {
        translation: {
          name: 'nombre',
          port: 'puerto',
          verbose: 'detallado',
          serve: 'servir',
          build: 'construir',
        },
      },
      'fr-FR': {
        translation: {
          name: 'nom',
          port: 'port',
          verbose: 'verbeux',
          serve: 'servir',
          build: 'construire',
        },
      },
    },
  });

  // You can change the language dynamically:
  // await i18next.changeLanguage('es-ES');

  await cli('server-app')
    // Pass i18next.t as the localization function
    // This integrates cli-forge with i18next's translation system
    .localize((key) => i18next.t(key))
    .option('name', {
      type: 'string',
      description: 'Server name',
      default: 'MyServer',
    })
    .option('port', {
      type: 'number',
      description: 'Port to listen on',
      default: 8080,
    })
    .option('verbose', {
      type: 'boolean',
      description: 'Enable verbose logging',
      alias: ['v'],
    })
    .command('serve', {
      builder: (cmd) => cmd,
      handler: (args) => {
        console.log('Starting server...');
        console.log(`Name: ${args.name}`);
        console.log(`Port: ${args.port}`);
        if (args.verbose) {
          console.log('Verbose logging enabled');
        }
      },
      description: 'Start the development server',
    })
    .command('build', {
      builder: (cmd) => cmd,
      handler: (args) => {
        console.log('Building application...');
        console.log(`Name: ${args.name}`);
        if (args.verbose) {
          console.log('Verbose logging enabled');
        }
      },
      description: 'Build for production',
    })
    .command('$0', {
      handler: (args) => {
        console.log('Starting server...');
        console.log(`Name: ${args.name}`);
        console.log(`Port: ${args.port}`);
        if (args.verbose) {
          console.log('Verbose logging enabled');
        }
      },
    })
    .forge();
}

main();

import cliForge from 'cli-forge';

const state = {
  defaultHost: 'example.com',
  auth: {} as Record<string, { user: string; pass?: string }>,
};

const cli = cliForge('interactive-subshell')
  // Enables launching an interactive subshell.
  // For this example, the subshell would be launched if the user
  // runs either:
  // - `node ./interactive-subshell.ts`
  // - `node ./interactive-subshell.ts foo`
  .enableInteractiveShell()
  .command('auth', {
    builder: (args) =>
      args
        .option('host', { type: 'string', default: state.defaultHost })
        .command('login', {
          builder: (args) => {
            return args
              .positional('user', { type: 'string', required: true })
              .option('pass', { type: 'string' });
          },
          handler: (args) => {
            state.auth ??= {};
            state.auth[args.host] = {
              user: args.user,
              pass: args.pass,
            };
            console.log('Logged in to', args.host, 'as', args.user);
          },
        })
        .command('logout', {
          handler: (args) => {
            delete state.auth[args.host];
            console.log('Logged out of', args.host);
          },
        }),
  })
  .command('lorem', {
    handler: (args) => {
      console.log('lorem ipsum');
    },
  });

// We export the CLI for a few reasons:
// - Testing
// - Composition (a CLI can be a subcommand of another CLI)
// - Docs generation
export default cli;

