import type { AuthContext, User } from '../types';

/**
 * Simulates looking up a user. In a real application, this might
 * query a database or validate a token.
 */
function lookupUser(): User {
  return {
    id: 'user-123',
    name: 'Jane Developer',
    role: 'admin',
  };
}

/**
 * Authentication middleware that adds user context to the args.
 *
 * This middleware demonstrates how to add typed properties that
 * downstream middleware and handlers can rely on.
 */
export function authMiddleware<T>(args: T): T & AuthContext {
  const user = lookupUser();

  return {
    ...args,
    user,
    authenticated: true,
  };
}

import type { TimingContext } from '../types';

/**
 * Generates a simple request ID for tracking.
 */
function generateRequestId(): string {
  return `req-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * Timing middleware that adds request timing context.
 *
 * The startTime can be used by handlers to calculate execution duration.
 * The requestId provides a correlation ID for logging.
 */
export function timingMiddleware<T>(args: T): T & TimingContext {
  return {
    ...args,
    startTime: Date.now(),
    requestId: generateRequestId(),
  };
}

/**
 * Helper to calculate elapsed time from a start timestamp.
 */
export function getElapsedMs(startTime: number): number {
  return Date.now() - startTime;
}

/**
 * Represents an authenticated user in the system.
 */
export interface User {
  id: string;
  name: string;
  role: 'admin' | 'user';
}

/**
 * Context added by the auth middleware.
 */
export interface AuthContext {
  user: User;
  authenticated: boolean;
}

/**
 * Context added by the timing middleware.
 */
export interface TimingContext {
  startTime: number;
  requestId: string;
}

