import { cli } from 'cli-forge';
import { runDeploy } from './deploy';

export const app = cli('deploy-tool')
  .option('logLevel', {
    type: 'string',
    default: 'info',
    description: 'Logging level',
  })
  .option('apiUrl', {
    type: 'string',
    required: true,
    description: 'API base URL',
  })
  // Register a logger provider whose factory receives the parsed args.
  // Any command handler can inject it without threading it through calls.
  .provide('logger', {
    factory: (args) => ({
      info: (msg: string) => console.log(`[${args.logLevel}] ${msg}`),
    }),
  })
  .command('deploy', {
    description: 'Deploy to a target environment',
    builder: (cmd) =>
      cmd.option('target', {
        type: 'string',
        required: true,
        description: 'Deployment target',
      }),
    handler: async () => {
      await runDeploy();
    },
  });

if (require.main === module) {
  app.forge();
}

import { getCommandContext } from 'cli-forge/context';
import { app } from './cli';

export async function runDeploy() {
  // Passing `app` as both the type witness and the runtime identity check.
  // The stored commandIdChain walks root -> deploy, so both the root and
  // any ancestor are valid references.
  const ctx = getCommandContext(app);
  const deployCtx = ctx.getChildContext('deploy');

  const logger = ctx.inject('logger');
  const target = deployCtx.args.target;

  logger.info(`Deploying to ${target}`);
}

import { cli } from 'cli-forge';
import { zodMiddleware } from 'cli-forge/middleware/zod';

import { deployConfigSchema, environments } from './schemas/config';
import { userSchema, roles } from './schemas/user';

const app = cli('validated-cli')
  .demandCommand()

  .command('deploy', {
    description: 'Deploy the application',
    builder: (cmd) =>
      cmd
        .option('env', {
          type: 'string',
          description: 'Deployment environment',
          choices: environments,
          required: true,
        })
        .option('replicas', {
          type: 'number',
          description: 'Number of replicas',
          default: 1,
        })
        .option('dryRun', {
          type: 'boolean',
          description: 'Preview deployment without executing',
        })
        .middleware(zodMiddleware(deployConfigSchema)),

    handler: (args) => {
      // TypeScript knows about transformed properties
      console.log(`Deploying to ${args.env}...`);
      console.log(`  replicas: ${args.replicas}`);
      console.log(`  requiresApproval: ${args.requiresApproval}`);
      console.log(`  timeout: ${args.defaultTimeout}s`);

      if (args.dryRun) {
        console.log('Dry run complete.');
      }
    },
  })

  .command('user-info', {
    description: 'Display user information',
    builder: (cmd) =>
      cmd
        .option('email', {
          type: 'string',
          description: 'User email address',
          required: true,
        })
        .option('role', {
          type: 'string',
          description: 'User role',
          choices: roles,
          required: true,
        })
        .option('name', {
          type: 'string',
          description: 'Display name',
        })
        .middleware(zodMiddleware(userSchema)),

    handler: (args) => {
      // Email is normalized, permission flags are computed
      console.log(`User Information:`);
      console.log(`  Email: ${args.email}`);
      console.log(`  Role: ${args.role}`);
      console.log(`  Can Edit: ${args.canEdit}`);
      console.log(`  Can Admin: ${args.canAdmin}`);

      if (args.name) {
        console.log(`  Name: ${args.name}`);
      }
    },
  });

export default app;

if (require.main === module) {
  app.forge();
}

import { z } from 'zod';

/**
 * Valid deployment environments.
 */
export const environments = ['development', 'staging', 'production'] as const;

/**
 * Deployment configuration schema.
 * Validates and transforms deployment options.
 */
export const deployConfigSchema = z
  .object({
    env: z.enum(environments),
    replicas: z.number().min(1).max(10),
    dryRun: z.boolean().optional(),
  })
  .transform((config) => ({
    ...config,
    // Add computed properties based on environment
    requiresApproval: config.env === 'production',
    defaultTimeout: config.env === 'production' ? 300 : 60,
  }));

/**
 * Type inferred from the schema output (after transform).
 */
export type DeployConfig = z.output<typeof deployConfigSchema>;

import { z } from 'zod';

/**
 * User roles with their permission levels.
 */
export const roles = ['viewer', 'editor', 'admin'] as const;
export type Role = (typeof roles)[number];

/**
 * User data schema with validation and normalization.
 */
export const userSchema = z
  .object({
    email: z.string().email('Invalid email format'),
    role: z.enum(roles),
    name: z.string().optional(),
  })
  .transform((user) => ({
    ...user,
    // Normalize email to lowercase
    email: user.email.toLowerCase(),
    // Compute permission flags based on role
    canEdit: user.role === 'editor' || user.role === 'admin',
    canAdmin: user.role === 'admin',
  }));

/**
 * Type inferred from the schema output.
 */
export type User = z.output<typeof userSchema>;

